<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="robots" content="noindex,nofollow"><title>Order Summary {{ $order->order_number }}</title><style>body{font:16px system-ui;max-width:900px;margin:2rem auto;color:#111}table{width:100%;border-collapse:collapse}th,td{padding:.6rem;border-bottom:1px solid #bbb;text-align:left}.notice{border:2px solid #8b6f2d;padding:1rem}@media print{button{display:none}body{margin:0}}</style></head><body><button onclick="print()">Print</button><h1>William Taylor</h1><div class="notice"><strong>Demo Order Summary</strong> — demonstration values only; not a tax invoice or payment receipt.</div><h2>{{ $order->order_number }}</h2><p>{{ $order->created_at->format('Y-m-d') }} · {{ str($order->status->value)->replace('_',' ')->title() }} · Payment: {{ str($order->payment_status->value)->replace('_',' ')->title() }}</p><h2>Customer</h2><p>{{ $order->customer_name }}<br>{{ $order->customer_email }}<br>{{ $order->customer_telephone }}<br>{!! nl2br(e($order->delivery_address)) !!}</p><table><thead><tr><th>Item</th><th>Quantity</th><th>Demo unit amount</th><th>Total</th></tr></thead><tbody>@foreach($order->items as $item)<tr><td>{{ $item->product_name }} {{ $item->variant_name }}</td><td>{{ $item->quantity }}</td><td>{{ \App\Domain\Orders\Support\OrderMoney::format($item->unit_amount_minor,$order->currency) }}</td><td>{{ \App\Domain\Orders\Support\OrderMoney::format($item->line_total_minor,$order->currency) }}</td></tr>@endforeach</tbody></table><h2>Total: {{ \App\Domain\Orders\Support\OrderMoney::format($order->total_minor,$order->currency) }}</h2>@if($order->customer_note)<p>{{ $order->customer_note }}</p>@endif</body></html>
